    ctx.shadowColor = 'transparent'; ctx.strokeStyle = 'rgba(255,236,200,0.95)'; ctx.lineWidth = 4; ctx.stroke();
    ctx.fillStyle = '#2a0d03'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(o.name, 540, y + 3);
