// ---------- FOUR MATHAS ----------
S.mathas = (t) => {
  const c1 = cue(1)[0];
  const snow = prog(t, c1 - 0.3, c1 + 0.5);
  cam(t, { z: lerp(1, 1.06, prog(t, 0, c1)) });
