  for (const [x, y, s] of [[300, 700, 1.2], [230, 790, 1], [340, 850, 0.9], [780, 690, 1.1], [860, 780, 1.3], [760, 860, 0.9], [180, 640, 0.8], [910, 900, 0.8]]) hillIcon(x, y, s);
