  ctx.fillStyle = 'rgba(255,205,140,0.6)'; ctx.beginPath(); ctx.moveTo(-90, -100); ctx.lineTo(-90, -360); ctx.quadraticCurveTo(0, -430, 90, -360); ctx.lineTo(90, -100); ctx.fill();   // lit back panel
