  ctx.fillStyle = 'rgba(70,32,12,0.9)'; ctx.beginPath(); ctx.arc(x - w / 4, y + 35, 7, 0, 7); ctx.arc(x + w / 4, y + 35, 7, 0, 7); ctx.fill();
