    if (k) textBlock('→', x - 155, 1040, 70, { alpha: g[k], color: GOLD }); });
  textBlock('दादा  ·  पिता  ·  पोता', 540, 330, 50, { alpha: g[2] * (1 - on(t, 1, 0, 0.3)) });
  followChip(t, 1);
