function ghorpad(x, y, s, t) {   // monitor lizard climbing upward
  ctx.save(); ctx.translate(x, y); ctx.rotate(-Math.PI / 2); ctx.scale(s, s); ctx.fillStyle = INK; const g = t * 6;
