    actor(700, 1180, 1.3, t, { face: -1, hat: 'turban', moustache: true, cloth: '#5a2a8a', ...poseMix(POSE.strike, POSE.guard, sw), wpn: 'sword', rot: fall * 1.3, ph: 3 });
