    rider(lerp(800, 470, prog(t, 0.4, at(0, 0.9))), lerp(380, 860, prog(t, 0.4, at(0, 0.9))) + 30, 0.3, t, { hat: 'turban', wpn: 'spear', fa: [1.9, -0.5], spearA: -1.3 });
    chip('मुहम्मद ग़ोरी', 540, 1180, 48, prog(t, 0.2, 0.7));
  } else {
