    if (t < c2 + 0.3) { for (let i = 0; i < 3; i++) elephant(-150 + i * 260 + (t - c1) * 90, 1200, 0.7, t, i);
      for (let i = 0; i < 6; i++) actor(700 + i * 90 + (t - c1) * 140, 1200, 0.65, t, { face: 1, walk: t * 9 + i, hat: 'turban', ...POSE.reach, lean: 0.25, ph: i });
