  stars(t, 0.6); moon(220, 360, 50);
  arsenal(760, 1180, 1.1);
  ground(1180);
  for (const x of [520, 1000]) redcoat(x, 1180, 0.85, { face: x < 700 ? -1 : -1, fa: [0.5, -1.3] });
  torch(600, 1180, 220, t, 1);
