  else for (let i = 0; i < 4; i++) leaves(260 + i * 190, 1170, 0.7, 4, 1, prog(t, c1 + 0.4 + i * 0.3, c1 + 1.4 + i * 0.3));
  chip('बख़्तियार ख़िलजी', 540, 260, 46, prog(t, 0.3, 0.8) * (1 - prog(t, c1 - 0.3, c1)));
